  '{"label_en":"Example margin course","label_sr":"Primer toka Margin Line","mode":"outline"}',
  '{"type":"margin_complete","objectId":"crown26-preparation"}',
  '[{"slug":"check-course","order":10,"title_en":"Inspect the complete loop","title_sr":"Pregledajte celu petlju","body_en":"Check that the line stays on the preparation and forms a closed loop.","body_sr":"Proverite da linija ostaje na preparaciji i formira zatvorenu petlju."}]');

select pg_temp.seed_phase16_step('full_crown_case','placement_and_path',20,'Position and inspect the restoration','Pozicionirajte i pregledajte restauraciju',
  'Select Crown restoration · 26. For this exercise set Z to 1.5 mm, then run the +Z insertion-direction preview on Preparation · 26.','Izaberite Crown restoration · 26. Za ovu vežbu postavite Z na 1,5 mm, pa pokrenite +Z smerni prikaz na Preparation · 26.',
  'The numeric transform and chosen direction are exercise settings. The directional preview is not a clinical undercut map.','Numerička transformacija i izabrani smer su podešavanja vežbe. Smerni prikaz nije klinička mapa podminiranja.',
