  '{"label_en":"Target for this exercise · crown placement","label_sr":"Cilj ove vežbe · pozicioniranje krunice","mode":"outline"}',
  '{"type":"transform_range","objectId":"crown26-restoration","field":"position","position":[0,0,1.5],"axes":["z"],"toleranceMm":0.2}',
  '[{"slug":"save-alignment","order":10,"title_en":"Keep the case aligned","title_sr":"Sačuvajte poravnanje slučaja","body_en":"Move only the editable restoration. Do not recenter the preparation or antagonist.","body_sr":"Pomerajte samo restauraciju koja se može menjati. Ne centrirajte ponovo preparaciju ili antagonistu."}]');

select pg_temp.seed_phase16_step('full_crown_case','proximal_and_occlusal_review',30,'Review neighboring surfaces','Pregledajte susedne površine',
  'Run Proximity map for Crown restoration · 26 and Adjacent tooth · 25. Then compare the crown with Antagonist · 36 using the same static proximity tool.','Pokrenite Proximity map za Crown restoration · 26 i Adjacent tooth · 25. Zatim uporedite krunicu sa Antagonist · 36 istim statičkim alatom za blizinu.',
  'These are static nearest-surface checks on the supplied synthetic positions, not dynamic occlusion or an articulator simulation.','Ovo su statičke provere najbližih površina na zadatim sintetičkim položajima, a ne dinamička okluzija ili simulacija artikulatora.',
