  '{"type":"analysis_target","kind":"contact","objectIds":["crown26-restoration","crown26-adjacent-25"],"maxValue":1.5}',
  '[{"slug":"read-map","order":10,"title_en":"Run an explicit map","title_sr":"Pokrenite eksplicitnu mapu","body_en":"A proximity map is computed on demand and becomes stale when either object changes.","body_sr":"Mapa blizine računa se na zahtev i postaje zastarela kada se promeni bilo koji objekat."}]');

select pg_temp.seed_phase16_step('full_crown_case','sculpt_and_thickness',40,'Sculpt and inspect thickness','Oblikujte i pregledajte debljinu',
  'Make one short sculpt stroke on Crown restoration · 26. Run Thickness on that restoration and review the section without changing the source preparation.','Napravite jedan kratak Sculpt potez na Crown restoration · 26. Pokrenite Thickness na restauraciji i pregledajte presek bez izmene izvorne preparacije.',
  'Target for this exercise: minimum measured thickness at least 0.8 mm. It is a configured synthetic exercise target, not a universal material recommendation.','Cilj ove vežbe: najmanja izmerena debljina je najmanje 0,8 mm. To je podešeni sintetički cilj vežbe, a ne univerzalna preporuka za materijal.',
  array['select','sculpt','analysis','camera'],array['crown26-restoration'],array['off','outline','transparent'],null,
  '{"label_en":"Target for this exercise · morphology and section","label_sr":"Cilj ove vežbe · morfologija i presek","mode":"outline"}',
  '{"type":"analysis_target","kind":"thickness","objectIds":["crown26-restoration"],"minValue":0.8}',
  '[{"slug":"compare","order":10,"title_en":"Compare before and after","title_sr":"Uporedite pre i posle","body_en":"Use Undo to compare the sculpt revision. Re-run thickness after any change; old results become stale.","body_sr":"Upotrebite Undo da uporedite reviziju Sculpt poteza. Posle svake izmene ponovo pokrenite Thickness; stari rezultati postaju zastareli."}]');

insert into public.scenarios(domain_id,slug,difficulty,title_en,title_sr,description_en,description_sr,patient_code,patient_age,indication_en,indication_sr,tooth_numbers,requirements_en,requirements_sr,additional_metadata,random_eligible,status,published_at)
select domain.id,'synthetic_posterior_crown_26','beginner','Posterior crown · tooth 26','Bočna krunica · zub 26',
  'Independent single-crown practice with supplied synthetic preparation, neighboring tooth and antagonist.','Samostalna vežba pojedinačne krunice uz sintetičku preparaciju, susedni zub i antagonistu.',
  'PT-SYN-026',null,'Single posterior crown','Pojedinačna bočna krunica',array[26]::smallint[],
  array['Inspect the preparation','Define a Margin Line','Position and sculpt the restoration','Review static proximity and thickness'],
  array['Pregledajte preparaciju','Definišite Margin Line','Pozicionirajte i oblikujte restauraciju','Pregledajte statičku blizinu i debljinu'],
  '{"material":{"en":"Synthetic training preset","sr":"Sintetički materijal za vežbu"},"supplied":{"en":["Preparation · 26","Adjacent tooth · 25","Antagonist · 36","Synthetic crown restoration"],"sr":["Preparation · 26","Susedni zub · 25","Antagonist · 36","Sintetička restauracija krunice"]},"notes":{"en":"Internally generated synthetic training geometry. Not a real patient case or clinically validated anatomy.","sr":"Interno generisana sintetička geometrija za vežbu. Nije stvarni slučaj niti klinički potvrđena anatomija."},"materialPreset":"synthetic_training","caseInitializer":"crown"}'::jsonb,true,'published',now()
from public.content_domains domain where domain.slug='crown'
on conflict(slug) do update set difficulty=excluded.difficulty,title_en=excluded.title_en,title_sr=excluded.title_sr,description_en=excluded.description_en,description_sr=excluded.description_sr,patient_code=excluded.patient_code,patient_age=excluded.patient_age,indication_en=excluded.indication_en,indication_sr=excluded.indication_sr,tooth_numbers=excluded.tooth_numbers,requirements_en=excluded.requirements_en,requirements_sr=excluded.requirements_sr,additional_metadata=excluded.additional_metadata,random_eligible=true,status='published',published_at=coalesce(public.scenarios.published_at,now());
